{"path": "two_bucket.py", "content": "from collections import deque


def measure(bucket_one, bucket_two, goal, start_bucket):
    if start_bucket not in ("one", "two"):
        raise ValueError("start_bucket must be 'one' or 'two'")
    if goal > max(bucket_one, bucket_two):
        raise ValueError("goal is larger than both buckets")
    caps = (bucket_one, bucket_two)
    start = (bucket_one, 0) if start_bucket == "one" else (0, bucket_two)
    forbidden = (0, bucket_two) if start_bucket == "one" else (bucket_one, 0)
    seen = {start}
    queue = deque([(start, 1)])
    while queue:
        (a, b), moves = queue.popleft()
        if a == goal:
            return moves, "one", b
        if b == goal:
            return moves, "two", a
        pour_ab = min(a, caps[1] - b)
        pour_ba = min(b, caps[0] - a)
        for state in (
            (caps[0], b), (a, caps[1]), (0, b), (a, 0),
            (a - pour_ab, b + pour_ab), (a + pour_ba, b - pour_ba),
        ):
            if state not in seen and state != forbidden:
                seen.add(state)
                queue.append((state, moves + 1))
    raise ValueError("goal is not reachable")
